<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(403);exit;}
require_once __DIR__.'/../app/bootstrap.php';
use App\Core\Database;
use App\Core\Env;
use App\Services\UserService;
use App\Services\TicketService;
use App\Services\ScenarioService;
use App\Services\SubmissionService;
use App\Services\NotebookService;
use App\Services\SocTrainingService;
if(Env::get('APP_ENV')!=='testing'||!str_ends_with((string)Env::get('DB_NAME'),'_test')||!in_array(Env::get('DB_HOST'),['127.0.0.1','localhost','::1'],true)){fwrite(STDERR,"REFUSED: isolated loopback _test database required.\n");exit(1);}
$passed=0;
$check=function(bool $ok,string $label)use(&$passed){if(!$ok)throw new RuntimeException('FAIL '.$label);$passed++;echo "PASS $label\n";};
$deny=function(callable $fn,string $label)use($check){try{$fn();}catch(\InvalidArgumentException|\App\Core\AccessDeniedException|\RuntimeException $e){$check(true,$label);return;}throw new RuntimeException('FAIL accepted '.$label);};
$count=function(string $table,string $where='1=1',array $params=[]):int{if(!in_array($table,['users','ticket_assignments','dataset_assignments','submissions','notifications','audit_logs'],true))throw new RuntimeException('Invalid table');return (int)Database::queryOne('SELECT COUNT(*) AS c FROM '.$table.' WHERE '.$where,$params)['c'];};
$db=Database::getInstance();$pdo=Database::getConnection();$tag='TRAIN-'.strtoupper(bin2hex(random_bytes(5)));
$users=new UserService();$tickets=new TicketService();$scenarios=new ScenarioService();$subs=new SubmissionService();$notebooks=new NotebookService();$soc=new SocTrainingService();
$before=$count('users');
try{
$admin=(int)(Database::queryOne("SELECT id FROM users WHERE role='ADMIN' AND status='ACTIVE' ORDER BY id LIMIT 1")['id']??0);if(!$admin)throw new RuntimeException('Test admin required.');
$pdo->beginTransaction();
$pw=bin2hex(random_bytes(16));$students=[];
for($i=0;$i<2;$i++)$students[]=$users->createStudent(['full_name'=>'Contract Student '.$i,'identifier'=>$tag.'-'.$i,'email'=>strtolower($tag).'-'.$i.'@example.invalid','password'=>$pw],$admin);
$a=(int)$students[0]['id'];$b=(int)$students[1]['id'];
$check($students[0]['role']==='STUDENT'&&(int)$students[0]['must_change_password']===1,'SOC creates only student with mandatory password rotation');
$deny(fn()=>$users->createStudent(['role'=>'ADMIN'],$admin),'Student management cannot create administrator');
$deny(fn()=>$users->createStudent(['full_name'=>'Forbidden'],$a),'Student actor cannot create users through shared service');
$deny(fn()=>$users->resetPassword($admin,bin2hex(random_bytes(16)),$admin),'Student password reset cannot target administrator');
$originalVersion=(int)$students[0]['session_version'];$nextPw=bin2hex(random_bytes(16));
$users->resetPassword($a,$nextPw,$admin);$after=$users->requireStudent($a);
$check((int)$after['session_version']===$originalVersion+1&&(int)$after['must_change_password']===1,'Password reset advances session version and requires change');
$n=$count('notifications','user_id=:id',['id'=>$a]);$v=(int)$after['session_version'];$users->resetPassword($a,$nextPw,$admin);
$check((int)$users->requireStudent($a)['session_version']===$v&&$count('notifications','user_id=:id',['id'=>$a])===$n,'Password-reset retry creates no duplicate notification or version bump');
$users->setStatus($a,'INACTIVE',$admin);$check($users->requireStudent($a)['status']==='INACTIVE','Student deactivation persists');
$deny(fn()=>$tickets->createTicket(['ticket_code'=>$tag.'-DENIED','title'=>'Denied actor'],$a),'Inactive student cannot create administrative ticket');
$users->setStatus($a,'ACTIVE',$admin);$check($users->requireStudent($a)['status']==='ACTIVE','Student activation persists');
$edited=$users->updateStudent($a,['full_name'=>'Edited Student','cohort'=>'Verified cohort'],$admin);$check($edited['full_name']==='Edited Student'&&$edited['cohort']==='Verified cohort','Student metadata edit persists');
$sc=$scenarios->createScenario(['code'=>$tag,'title'=>'Integration scenario','builder_metadata'=>['schema_version'=>1,'form_fields'=>['dim-weight-1'=>'100'],'workflow'=>[],'datasets'=>[]]],$admin);$scid=(int)$sc['id'];
$published=$soc->scenarioAction($scid,'publish',$admin);$check($published['status']==='PUBLISHED','SOC publish persists legal review and published transitions');
$history=count($published['builder_metadata']['history']);$soc->scenarioAction($scid,'publish',$admin);$check(count($scenarios->getScenario($scid)['builder_metadata']['history'])===$history,'Scenario publish retry is idempotent');
$t=$tickets->createTicket(['ticket_code'=>$tag.'-T','title'=>'Initial ticket','scenario_id'=>$scid,'student_id'=>$a,'requirements'=>'Real requirement','acceptance_criteria'=>'Instructor checks','deadline'=>'2027-01-01 12:00:12'],$admin);$tid=(int)$t['id'];
$check($t['status']==='ASSIGNED','Ticket creation with initial active student persists assignment');
$notes=$count('notifications','user_id=:id',['id'=>$a]);$events=$count('audit_logs','action=:action AND resource_id=:id',['action'=>'TICKET_ASSIGNED','id'=>$tid]);
$tickets->assignTicket($tid,$a,$admin);$tickets->assignTicket($tid,$a,$admin);
$check($count('ticket_assignments','ticket_id=:id',['id'=>$tid])===1&&$count('notifications','user_id=:id',['id'=>$a])===$notes,'Duplicate ticket assignment adds no row or notification');
$tickets->updateTicket($tid,['title'=>'Edited ticket','requirements'=>'Edited requirement','deadline'=>'2027-02-01T09:15:31'],$admin,'ADMIN');
$view=$tickets->getTicket($tid,$a,'STUDENT');$check($view['title']==='Edited ticket'&&$view['requirements']==='Edited requirement'&&$view['deadline']==='2027-02-01 09:15:31','SOC metadata edit keeps exact requirements and deadline seconds');
$deny(fn()=>$tickets->updateTicket($tid,['priority'=>'CRITICAL'],$a,'ADMIN'),'Frontend-provided ADMIN role cannot elevate student');
$deny(fn()=>$tickets->updateTicket($tid,['status'=>'APPROVED'],$admin,'ADMIN'),'Arbitrary administrative approval status rejected');
$deny(fn()=>$tickets->getTicket($tid,$b,'STUDENT'),'Unassigned student cannot inspect ticket');
$tickets->updateTicket($tid,['status'=>'IN_PROGRESS'],$a,'STUDENT');$tickets->updateTicket($tid,['status'=>'IN_PROGRESS'],$a,'STUDENT');
$check($tickets->getTicket($tid,$a,'STUDENT')['status']==='IN_PROGRESS','Progress persists and identical retry is safe');
$tickets->addComment($tid,$a,'Saved progress commentary');$check(count($tickets->getTicket($tid,$admin,'ADMIN')['comments'])===1,'Ticket comments are persisted and visible in SOC');
$deny(fn()=>$tickets->addComment($tid,$b,'Denied'),'Foreign student cannot comment');
$nb=$notebooks->createNotebook(['title'=>'Student-owned history','ticket_id'=>$tid,'cells'=>[['cell_type'=>'code','source'=>'# preserved source']]],$a);$nid=(int)$nb['id'];
$dataset=$db->insert('datasets',['code'=>$tag.'-DS','name'=>'Transaction-only relationship','format'=>'csv','file_path'=>'INTENTIONALLY_ABSENT_CONTRACT_FILE.csv','checksum_sha256'=>str_repeat('0',64),'uploaded_by'=>$admin]);
$db->insert('dataset_assignments',['dataset_id'=>$dataset,'student_id'=>$a,'ticket_id'=>$tid,'assigned_by'=>$admin]);
$tickets->reassignTicket($tid,$b,$admin,'New active owner');
$check($tickets->getTicket($tid,$b,'STUDENT')['status']==='ASSIGNED','Reassignment activates new student and resets open progress');
$deny(fn()=>$tickets->getTicket($tid,$a,'STUDENT'),'Previous student ticket access is revoked');
$check($count('ticket_assignments','ticket_id=:id AND revoked_at IS NOT NULL',['id'=>$tid])===1,'Historical ticket assignment retained');
$check($count('dataset_assignments','ticket_id=:id AND revoked_at IS NOT NULL',['id'=>$tid])===1,'Prior dataset access revoked without deleting assignment');
$check((int)$notebooks->getNotebook($nid,$a,'STUDENT')['student_id']===$a,'Reassignment never transfers previous student notebook');
$deny(fn()=>$notebooks->getNotebook($nid,$b,'STUDENT'),'New assigned student cannot read previous student notebook');
$n=$count('notifications');$tickets->reassignTicket($tid,$b,$admin,'Same target retry');$check($count('notifications')===$n,'Reassignment retry creates no duplicate notification');
$deny(fn()=>$subs->createSubmission(['ticket_id'=>$tid,'notebook_id'=>$nid],$b),'Cannot submit previous student notebook after reassignment');
$tickets->updateTicket($tid,['status'=>'IN_PROGRESS'],$b,'STUDENT');
$body=['ticket_id'=>$tid,'notes'=>'Complete work','request_key'=>$tag.'-REQ1'];$sub=$subs->createSubmission($body,$b);$subid=(int)$sub['id'];$n=$count('notifications');$c=$count('submissions');
$retry=$subs->createSubmission($body,$b);$check((int)$retry['id']===$subid&&$count('submissions')===$c&&$count('notifications')===$n,'Duplicate submission key returns same persisted work without duplicate events');
$deny(fn()=>$subs->createSubmission($body+['model_id'=>999999],$b),'Reused idempotency key with changed payload rejected');
$review=$subs->reviewSubmission($subid,['status'=>'CHANGES_REQUESTED','feedback'=>'Revise detail','total_score'=>82.25],$admin);
$check((float)$review['total_score']===82.25,'Fractional instructor grade preserved exactly');
$n=$count('notifications');$review2=$subs->reviewSubmission($subid,['status'=>'CHANGES_REQUESTED','feedback'=>'Revise detail','total_score'=>82.25],$admin);
$check((int)$review2['id']===$subid&&$count('notifications')===$n,'Review retry does not create duplicate student notification');
$deny(fn()=>$subs->reviewSubmission($subid,['status'=>'APPROVED'],$admin),'Conflicting second review rejected');
$check($tickets->getTicket($tid,$b,'STUDENT')['status']==='CHANGES_REQUESTED','Review decision appears in assigned student ticket');
$tickets->updateTicket($tid,['status'=>'IN_PROGRESS'],$b,'STUDENT');
$new=$subs->createSubmission(['ticket_id'=>$tid,'notes'=>'Revised detail','request_key'=>$tag.'-REQ2'],$b);$check((int)$new['iteration']===2,'Revision creates next student iteration');
$subs->reviewSubmission((int)$new['id'],['status'=>'APPROVED','feedback'=>'Accepted'],$admin);
$check($tickets->getTicket($tid,$b,'STUDENT')['status']==='APPROVED','Approval updates associated ticket in same transaction');
$deny(fn()=>$tickets->reassignTicket($tid,$a,$admin),'Completed ticket cannot be reassigned');
$progress=$soc->studentResource($b,'progress',$admin);$check($progress['submissions']===2,'SOC student progress reads actual submission count');
$cancel=$tickets->createTicket(['ticket_code'=>$tag.'-C','title'=>'Cancellation work','student_id'=>$a],$admin);$cid=(int)$cancel['id'];
$tickets->updateTicket($cid,['status'=>'CANCELLED'],$admin,'ADMIN');$n=$count('notifications');$tickets->updateTicket($cid,['status'=>'CANCELLED'],$admin,'ADMIN');
$check($tickets->getTicket($cid,$a,'STUDENT')['status']==='CANCELLED'&&$count('notifications')===$n,'Cancellation visible to assigned student and retry idempotent');
$deny(fn()=>$tickets->updateTicket($cid,['status'=>'IN_PROGRESS'],$a,'STUDENT'),'Cancelled work cannot resume');
$check(count($soc->ticketResource($tid,'students',$admin))===2,'SOC inspection retains current and historical assignments');
$check(count($soc->scenarioResource($scid,'students',$admin))===1,'Scenario current student count excludes revoked assignment');
$pdo->rollBack();$check($count('users')===$before,'All generated records rolled back; existing students unchanged');
echo "PASS $passed training integration checks on ".Env::get('DB_NAME')."; all rows rolled back.\n";
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();fwrite(STDERR,$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);}
